class PCG {
public:
    void solve(const Matrix& A, const Vector& b, Vector& x) {
        int n = A.rows();
        Vector r = b - A * x;  // Initial residual
        Vector p = r;
        double alpha = 0.0, beta = 0.0;

        for (int k = 0; k < n; ++k) {
            double alpha_denom = r.dot(r);
            if (alpha_denom == 0.0) {
                throw std::runtime_error("CG solver failed to converge");
            }
            Vector Ap = A * p;
            alpha = alpha_denom / p.dot(Ap);
            x += alpha * p;
            r -= alpha * Ap;

            beta = -r.dot(r) / alpha_denom;
            p = r + beta * p;
        }

        // Convergence check is typically done outside this loop
    }
};
```

### Step 3: Summarize the Iteration Logic

Based on the partial code snippet provided, here is how the CG solver iterates:

1. **Initialization**:
